-- User approval: Telegram7487759 explicitly grants both Platform Owner and
-- Sub-owner read visibility across all companies, with no extra operational writes.
-- Every successful RPC read writes an audit event in the same transaction.
-- Fixed columns avoid granting future secret columns automatically.
-- before_values/after_values contain tenant record history and may include PII.
-- This is part of approved company-data visibility, not access to auth secrets.
begin;
create or replace function api.platform_read_company(p_tenant_id uuid,p_resource text,p_limit integer default 50,p_offset integer default 0)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_query text;v_rows jsonb;v_event bigint;
begin
 if not private.is_platform_operator() then raise exception 'platform_read_not_authorized' using errcode='42501';end if;
 if p_tenant_id is null or not exists(select 1 from core.tenants where id=p_tenant_id) then
  raise exception 'company_not_found' using errcode='22023';end if;
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset not between 0 and 10000 then
  raise exception 'platform_read_page_invalid' using errcode='22023';end if;
 case p_resource
 when 'audit.events' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.actor_user_id,r.action_key,r.record_type,r.record_id,r.summary,r.created_at,r.actor_membership_id,r.scope_kind,r.request_id from audit.events r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.entitlement_grants' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.module_key,r.feature_key,r.membership_id,r.starts_at,r.expires_at,r.granted_by,r.reason,r.billing_treatment,r.source_kind,r.legacy_entitlement_id,r.status,r.bill_to_tenant_id,r.currency,r.unit_price_minor,r.quota,r.revoked_at,r.revoked_by,r.revoke_reason,r.created_at from core.entitlement_grants r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.features' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.feature_key,r.module_key,r.label,r.description,r.enabled,r.usage_unit from core.features r where true order by r.feature_key,r.module_key,r.label limit $2 offset $3) page';
 when 'core.invoice_items' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.invoice_id,r.usage_event_id,r.grant_id,r.subscription_item_id,r.description,r.service_period_start,r.service_period_end,r.quantity,r.unit_price_minor,r.amount_minor,r.currency from core.invoice_items r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.invoices' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.invoice_number,r.status,r.currency,r.period_start,r.period_end,r.subtotal_minor,r.tax_minor,r.total_minor,r.issued_at,r.due_at,r.created_by,r.created_at from core.invoices r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.modules' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.module_key,r.label,r.enabled from core.modules r where true order by r.module_key,r.label,r.enabled limit $2 offset $3) page';
 when 'core.org_units' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.parent_id,r.name,r.created_at from core.org_units r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.payments' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.invoice_id,r.provider,r.provider_reference,r.status,r.amount_minor,r.currency,r.occurred_at from core.payments r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.plan_entitlements' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.plan_id,r.module_key,r.feature_key,r.quota,r.usage_rate_minor,r.usage_currency from core.plan_entitlements r where exists(select 1 from core.subscriptions s where s.plan_id=r.plan_id and s.tenant_id=$1) order by r.id limit $2 offset $3) page';
 when 'core.plans' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.plan_key,r.version,r.name,r.status,r.currency,r.price_minor,r.created_at from core.plans r where exists(select 1 from core.subscriptions s where s.plan_id=r.id and s.tenant_id=$1) order by r.id limit $2 offset $3) page';
 when 'core.sites' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.org_unit_id,r.name,r.code,r.city,r.status,r.created_at from core.sites r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.subscription_items' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.subscription_id,r.plan_entitlement_id,r.quantity,r.unit_price_minor,r.currency,r.starts_at,r.ends_at from core.subscription_items r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.subscriptions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.plan_id,r.status,r.starts_at,r.current_period_start,r.current_period_end,r.cancel_at_period_end,r.canceled_at,r.created_by,r.created_at from core.subscriptions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.tenant_domains' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.domain_name,r.status,r.verified_at,r.created_by,r.created_at from core.tenant_domains r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.tenant_entitlements' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.module_key,r.status,r.valid_to,r.changed_by,r.created_at from core.tenant_entitlements r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'core.tenants' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.name,r.industry_label,r.status,r.created_by,r.created_at from core.tenants r where r.id=$1 order by r.id limit $2 offset $3) page';
 when 'core.usage_events' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.beneficiary_membership_id,r.feature_key,r.grant_id,r.payer_tenant_id,r.billing_treatment,r.idempotency_key,r.usage_unit,r.quantity,r.occurred_at,r.unit_price_minor,r.currency from core.usage_events r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.action_updates' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.action_id,r.actor_membership_id,r.actor_user_id,r.status,r.comment,r.created_at from hse.action_updates r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.contractor_organizations' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.name,r.external_reference,r.status,r.created_by,r.created_at,r.updated_at from hse.contractor_organizations r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.corrective_actions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.site_id,r.finding_id,r.inspection_id,r.title,r.description,r.owner_membership_id,r.priority,r.status,r.response_due_at,r.plan_due_at,r.closure_due_at,r.revision,r.created_by,r.created_at,r.updated_at from hse.corrective_actions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.engagement_supervisor_notes' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.engagement_id,r.author_membership_id,r.note,r.created_at from hse.engagement_supervisor_notes r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.evidence_files' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.site_id,r.linked_record_type,r.linked_record_id,r.file_name,r.mime_type,r.size_bytes,r.status,r.uploaded_by,r.created_at from hse.evidence_files r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.findings' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.site_id,r.inspection_id,r.question_id,r.title,r.description,r.priority,r.status,r.created_by,r.created_at,r.updated_at from hse.findings r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.follow_ups' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.action_id,r.title,r.owner_membership_id,r.due_at,r.status,r.outcome,r.created_at,r.updated_at from hse.follow_ups r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.form_templates' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.title,r.category,r.status,r.revision,r.definition,r.owner_membership_id,r.created_by,r.created_at,r.updated_at from hse.form_templates r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.form_versions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.template_id,r.version,r.snapshot,r.published_by,r.published_at from hse.form_versions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.inspection_reviews' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.inspection_id,r.stage,r.decision,r.actor_membership_id,r.actor_user_id,r.reason,r.revision,r.created_at from hse.inspection_reviews r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.inspections' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.site_id,r.template_id,r.form_version_id,r.title,r.inspector_membership_id,r.status,r.current_stage,r.answers,r.revision,r.created_at,r.submitted_at,r.updated_at from hse.inspections r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.people' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.display_name,r.person_kind,r.status,r.worker_number,r.membership_id,r.created_by,r.created_at,r.updated_at from hse.people r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.person_engagement_events' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.person_id,r.engagement_id,r.event_type,r.actor_user_id,r.actor_membership_id,r.occurred_at,r.reason,r.before_values,r.after_values,r.supersedes_event_id,r.request_id from hse.person_engagement_events r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'hse.person_engagements' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.person_id,r.engagement_type,r.contractor_organization_id,r.site_id,r.org_unit_id,r.starts_at,r.ends_at,r.status,r.job_title_snapshot,r.external_worker_reference,r.created_by,r.created_at,r.updated_at from hse.person_engagements r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.delegation_envelopes' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.grantor_membership_id,r.delegate_membership_id,r.level,r.site_id,r.org_unit_id,r.allowed_capabilities,r.starts_at,r.ends_at,r.status,r.created_by,r.created_at,r.revoked_by,r.revoked_at,r.revoke_reason,r.parent_envelope_id from iam.delegation_envelopes r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.delegation_review_events' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.envelope_id,r.actor_user_id,r.action,r.previous_ends_at,r.new_ends_at,r.reason,r.occurred_at from iam.delegation_review_events r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.engagement_supervisors' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.engagement_id,r.starts_at,r.ends_at,r.status,r.created_by,r.reason from iam.engagement_supervisors r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.invitations' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.email,r.intended_level,r.invited_by,r.created_at,r.expires_at,r.accepted_at,r.accepted_by,r.revoked_at,r.revoked_by,r.revoke_reason from iam.invitations r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.member_permission_decisions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.permission_key,r.decision,r.scope_kind,r.site_id,r.org_unit_id,r.task_kind,r.task_id,r.can_read,r.can_write,r.exception_kind,r.status,r.granted_by,r.starts_at,r.ends_at,r.reason,r.revoked_at,r.revoked_by,r.revoke_reason,r.created_at,r.source_delegation_id from iam.member_permission_decisions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.member_permissions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.permission_key,r.scope_kind,r.site_id,r.can_read,r.can_write,r.granted_by,r.active,r.created_at,r.org_unit_id,r.task_id from iam.member_permissions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.membership_permission_profiles' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.role_family,r.profile_id,r.profile_version_id,r.source,r.assigned_by,r.assigned_at,r.is_current,r.source_delegation_id from iam.membership_permission_profiles r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.membership_role_org_units' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_role_id,r.org_unit_id,r.granted_by,r.granted_at,r.ends_at,r.revoked_at,r.revoked_by,r.revoke_reason from iam.membership_role_org_units r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.membership_role_sites' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_role_id,r.site_id,r.granted_by,r.granted_at,r.ends_at,r.revoked_at,r.revoked_by,r.revoke_reason from iam.membership_role_sites r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.membership_roles' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.role_id,r.starts_at,r.ends_at,r.granted_by,r.revoked_at,r.revoked_by,r.revoke_reason,r.role_version_id,r.source_delegation_id from iam.membership_roles r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.memberships' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.user_id,r.member_role,r.status,r.display_name,r.email,r.created_at,r.updated_at from iam.memberships r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.org_unit_access' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.tenant_id,r.membership_id,r.org_unit_id,r.granted_by,r.active,r.created_at from iam.org_unit_access r where r.tenant_id=$1 order by r.tenant_id,r.membership_id,r.org_unit_id limit $2 offset $3) page';
 when 'iam.permission_action_grants' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.permission_key,r.action_key,r.scope_kind,r.site_id,r.org_unit_id,r.task_kind,r.task_id,r.starts_at,r.ends_at,r.status,r.decision,r.source_delegation_id,r.created_by,r.reason from iam.permission_action_grants r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.permission_catalog' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.permission_key,r.module_key,r.label,r.description,r.enabled,r.feature_key,r.supported_actions,r.supported_scope_kinds,r.requires_reason,r.is_sensitive from iam.permission_catalog r where true order by r.permission_key,r.module_key,r.label limit $2 offset $3) page';
 when 'iam.permission_profile_applications' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.profile_id,r.profile_version_id,r.target_mode,r.target_membership_ids,r.applied_by,r.applied_at from iam.permission_profile_applications r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.permission_profile_defaults' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.tenant_id,r.role_family,r.profile_id,r.profile_version_id,r.updated_by,r.updated_at,r.source_delegation_id from iam.permission_profile_defaults r where r.tenant_id=$1 order by r.tenant_id,r.role_family,r.profile_id limit $2 offset $3) page';
 when 'iam.permission_profile_permissions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.profile_version_id,r.permission_key,r.scope_kind,r.site_id,r.org_unit_id,r.can_read,r.can_write,r.actions from iam.permission_profile_permissions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.permission_profile_versions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.profile_id,r.version_no,r.created_by,r.created_at,r.sealed from iam.permission_profile_versions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.permission_profiles' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.role_family,r.profile_name,r.current_version,r.active,r.created_by,r.created_at from iam.permission_profiles r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.phase1_role_family_review' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.tenant_id,r.role_id,r.role_key,r.reason,r.observed_admin_assignments,r.observed_employee_assignments,r.recorded_at,r.resolved_at,r.resolved_by from iam.phase1_role_family_review r where r.tenant_id=$1 order by r.tenant_id,r.role_id,r.role_key limit $2 offset $3) page';
 when 'iam.role_permissions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.role_id,r.permission_key,r.scope_kind,r.can_read,r.can_write,r.active from iam.role_permissions r where exists(select 1 from iam.roles owner where owner.id=r.role_id and owner.tenant_id=$1) order by r.role_id,r.permission_key,r.scope_kind limit $2 offset $3) page';
 when 'iam.role_version_permissions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.role_version_id,r.permission_key,r.scope_kind,r.can_read,r.can_write,r.tenant_id,r.actions from iam.role_version_permissions r where r.tenant_id=$1 order by r.role_version_id,r.permission_key,r.scope_kind limit $2 offset $3) page';
 when 'iam.role_versions' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.role_id,r.version_no,r.role_family,r.status,r.created_by,r.created_at,r.published_at from iam.role_versions r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.roles' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.role_key,r.label,r.protected,r.active,r.created_by,r.created_at,r.role_family,r.phase1_legacy_unclassified from iam.roles r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.site_access' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.tenant_id,r.membership_id,r.site_id,r.granted_by,r.active,r.created_at from iam.site_access r where r.tenant_id=$1 order by r.tenant_id,r.membership_id,r.site_id limit $2 offset $3) page';
 when 'iam.superadmin_capability_limits' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.tenant_id,r.membership_id,r.capability_key,r.can_use,r.can_delegate,r.set_by,r.reason,r.updated_at from iam.superadmin_capability_limits r where r.tenant_id=$1 order by r.tenant_id,r.membership_id,r.capability_key limit $2 offset $3) page';
 when 'iam.superadmin_invitation_limits' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.invitation_id,r.membership_id,r.permission_key,r.can_use,r.can_delegate,r.set_by,r.reason,r.created_at from iam.superadmin_invitation_limits r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 when 'iam.task_assignments' then v_query:='select coalesce(jsonb_agg(to_jsonb(page)),''[]''::jsonb) from (select r.id,r.tenant_id,r.membership_id,r.task_kind,r.task_id,r.assigned_by,r.active,r.created_at,r.site_id,r.org_unit_id from iam.task_assignments r where r.tenant_id=$1 order by r.id limit $2 offset $3) page';
 else raise exception 'platform_read_resource_not_allowed' using errcode='22023';end case;
 execute v_query into v_rows using p_tenant_id,p_limit,p_offset;
 insert into audit.events(tenant_id,actor_user_id,scope_kind,action_key,record_type,record_id,summary)
 values(p_tenant_id,private.request_actor_id(),'tenant','platform.company_data.read',p_resource,p_tenant_id,
  jsonb_build_object('limit',p_limit,'offset',p_offset,'returned',jsonb_array_length(v_rows))) returning id into v_event;
 return jsonb_build_object('rows',v_rows,'limit',p_limit,'offset',p_offset,'audit_event_id',v_event);
end $$;
create or replace function api.platform_list_companies(p_limit integer default 50,p_offset integer default 0)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_rows jsonb;v_event bigint;
begin
 if not private.is_platform_operator() then raise exception 'platform_read_not_authorized' using errcode='42501';end if;
 if p_limit is null or p_limit not between 1 and 100 or p_offset is null or p_offset not between 0 and 10000 then
  raise exception 'platform_read_page_invalid' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(page)),'[]'::jsonb) into v_rows from (
  select id,name,industry_label,status,created_at from core.tenants order by id limit p_limit offset p_offset) page;
 insert into audit.events(tenant_id,actor_user_id,scope_kind,action_key,record_type,summary)
 values(null,private.request_actor_id(),'platform','platform.companies.list','core.tenants',
  jsonb_build_object('limit',p_limit,'offset',p_offset,'returned',jsonb_array_length(v_rows))) returning id into v_event;
 return jsonb_build_object('rows',v_rows,'limit',p_limit,'offset',p_offset,'audit_event_id',v_event);
end $$;
revoke all on function api.platform_read_company(uuid,text,integer,integer),api.platform_list_companies(integer,integer) from public,anon,service_role;
grant execute on function api.platform_read_company(uuid,text,integer,integer),api.platform_list_companies(integer,integer) to authenticated;
